package com.projetok.studio;

import com.projetok.rpg.*;
import java.awt.*;
import java.awt.event.*;
import java.nio.file.*;
import java.util.*;
import javax.swing.*;
import javax.swing.event.*;

/** Editor visual de .sgquest, com I/O assíncrono e referências dos catálogos reais. */
public final class QuestBuilder extends JFrame {
    final DefaultListModel<QuestBook.Draft> model=new DefaultListModel<>();
    final JList<QuestBook.Draft> list=new JList<>(model);
    final JTextField search=new JTextField(),id=new JTextField(),name=new JTextField(),prerequisites=new JTextField();
    final JTextArea description=new JTextArea(5,25),diagnostics=new JTextArea(4,30);
    final JComboBox<String> npc=references("npc"),region=references("region"),item=references("item"),race=new JComboBox<>(),domain=new JComboBox<>();
    final JSpinner level=new JSpinner(new SpinnerNumberModel(1,1,1000,1)),xp=new JSpinner(new SpinnerNumberModel(3,0,10000,1)),coins=new JSpinner(new SpinnerNumberModel(5,0,10000,1)),quantity=new JSpinner(new SpinnerNumberModel(1,1,99,1));
    final JCheckBox unchosen=new JCheckBox("Exigir domínio não escolhido"),reset=new JCheckBox("Contrato de reset (somente validação)");
    final DefaultListModel<QuestService.Objective> objectives=new DefaultListModel<>();final JList<QuestService.Objective> objectiveList=new JList<>(objectives);
    final JLabel status=new JLabel("Autoria experimental | playtest sintético | save V2 preservado");
    final java.util.List<QuestBook.Draft> quests=new ArrayList<>();
    QuestBook.Draft selected;Path file;boolean dirty,busy,loading;
    static JComboBox<String> references(String kind){return new JComboBox<>(RpgContent.builtin().all(kind).stream().map(RpgContent.Definition::id).sorted().toArray(String[]::new));}
    /** Abre uma biblioteca de missões sem carregar personagens pessoais. */
    public QuestBuilder(Path project){
        super("Spirit Gate | Quest Builder experimental");setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);setSize(1250,850);setMinimumSize(new Dimension(1000,650));
        race.addItem("");CharacterRaces.all().forEach(r->race.addItem(r.id()));race.addActionListener(e->domains());domains();
        JPanel left=new JPanel(new BorderLayout(4,4));search.setToolTipText("Buscar missão por ID ou nome");left.add(search,BorderLayout.NORTH);left.add(new JScrollPane(list));
        list.setCellRenderer((l,q,i,s,f)->{var label=new JLabel(q.name()+" ["+q.id()+"]");label.setOpaque(true);label.setForeground(StudioTheme.TEXT);label.setBackground(s?StudioTheme.SELECTED:StudioTheme.FIELD);label.setBorder(BorderFactory.createEmptyBorder(7,6,7,6));return label;});
        search.getDocument().addDocumentListener(new DocumentListener(){public void insertUpdate(DocumentEvent e){filter();}public void removeUpdate(DocumentEvent e){filter();}public void changedUpdate(DocumentEvent e){filter();}});
        list.addListSelectionListener(e->{if(!loading&&!e.getValueIsAdjusting()&&list.getSelectedValue()!=null){try{commit();show(list.getSelectedValue());}catch(Exception error){problem(error);}}});
        JPanel center=new JPanel(new BorderLayout());center.setBorder(BorderFactory.createTitledBorder("Objetivos e dependências"));center.add(new JScrollPane(objectiveList));
        JPanel objectiveButtons=new JPanel(new GridLayout(0,2,4,4));button(objectiveButtons,"Adicionar objetivo",this::addObjective);button(objectiveButtons,"Remover objetivo",()->{int i=objectiveList.getSelectedIndex();if(i>=0)objectives.remove(i);dirty=true;});button(objectiveButtons,"Subir",()->move(-1));button(objectiveButtons,"Descer",()->move(1));center.add(objectiveButtons,BorderLayout.SOUTH);
        JPanel form=new JPanel(new GridLayout(0,2,6,6));for(Object[] row:new Object[][]{{"ID",id},{"Nome",name},{"NPC inicial",npc},{"Região",region},{"Raça (vazio: qualquer)",race},{"Nível mínimo",level},{"Domínio (nível 15+)",domain},{"Pré-requisitos (IDs por vírgula)",prerequisites},{"XP geral",xp},{"Moedas do RPG",coins},{"Item",item},{"Quantidade",quantity}}){form.add(new JLabel((String)row[0]));form.add((Component)row[1]);}form.add(unchosen);form.add(reset);
        JPanel right=new JPanel(new BorderLayout(4,4));right.setBorder(BorderFactory.createTitledBorder("Propriedades e recompensa"));right.add(form,BorderLayout.NORTH);description.setLineWrap(true);description.setWrapStyleWord(true);right.add(new JScrollPane(description));
        JSplitPane middle=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,center,right);middle.setResizeWeight(.45);JSplitPane all=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,left,middle);all.setDividerLocation(260);
        JToolBar toolbar=new JToolBar();toolbar.setFloatable(false);button(toolbar,"Criar",this::create);button(toolbar,"Duplicar",this::duplicate);button(toolbar,"Aplicar edição",()->{commit();filter();});button(toolbar,"Validar",this::validateBook);button(toolbar,"Abrir",this::open);button(toolbar,"Salvar",()->save(false));button(toolbar,"Exportar para teste",()->save(true));
        button(toolbar,"Testar no RPG",()->QuestPlaytest.launch(this,book(),project));
        diagnostics.setEditable(false);diagnostics.setLineWrap(true);JPanel bottom=new JPanel(new BorderLayout());bottom.add(new JScrollPane(diagnostics));bottom.add(status,BorderLayout.SOUTH);
        setLayout(new BorderLayout(6,6));add(toolbar,BorderLayout.NORTH);add(all);add(bottom,BorderLayout.SOUTH);addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){try{if(!busy&&discard())dispose();}catch(Exception error){problem(error);}}});
        for(int i=0;i<form.getComponentCount()-1;i+=2)if(form.getComponent(i) instanceof JLabel label){label.setLabelFor(form.getComponent(i+1));form.getComponent(i+1).getAccessibleContext().setAccessibleName(label.getText());}
        button(toolbar,"Recuperar backup",()->openBackup());
        for(var entry:new Object[][]{{"control S",(Runnable)()->save(false)},{"control O",(Runnable)this::open}}){String key=(String)entry[0];getRootPane().getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW).put(KeyStroke.getKeyStroke(key),key);getRootPane().getActionMap().put(key,new AbstractAction(){public void actionPerformed(ActionEvent e){((Runnable)entry[1]).run();}});}
        StudioTheme.apply(getContentPane());create();
    }
    void button(Container panel,String title,Runnable work){JButton b=new JButton(title);b.addActionListener(e->{if(busy)return;try{work.run();}catch(Exception error){problem(error);}});panel.add(b);}
    void domains(){Object previous=domain.getSelectedItem();domain.removeAllItems();domain.addItem("");String selected=(String)race.getSelectedItem();if(selected!=null&&!selected.isEmpty())Domains.forRace(selected).forEach(d->domain.addItem(d.id()));if(previous!=null)for(int i=0;i<domain.getItemCount();i++)if(previous.equals(domain.getItemAt(i)))domain.setSelectedIndex(i);}
    void filter(){loading=true;try{model.clear();String term=search.getText().toLowerCase(Locale.ROOT);quests.stream().filter(q->(q.id()+" "+q.name()).toLowerCase(Locale.ROOT).contains(term)).forEach(model::addElement);}finally{loading=false;}}
    String unique(){for(int i=1;i<10000;i++){String candidate="missao_"+i;if(quests.stream().noneMatch(q->q.id().equals(candidate)))return candidate;}throw new IllegalStateException("Limite de IDs atingido");}
    void create(){if(selected!=null)commit();String next=unique();var q=new QuestBook.Draft(next,"Nova missão","Descreva o objetivo.","elder","village","",1,"",false,java.util.List.of(),new QuestService.Definition(java.util.List.of(new QuestService.Objective("visit","village",1)),3,5,"potion",1),false);quests.add(q);show(q);filter();dirty=true;}
    void duplicate(){commit();var q=selected;var copy=new QuestBook.Draft(unique(),q.name()+" cópia",q.description(),q.npc(),q.region(),q.race(),q.minimumLevel(),q.domain(),q.unchosenDomain(),q.prerequisites(),q.definition(),q.resetContract());quests.add(copy);show(copy);filter();dirty=true;}
    void show(QuestBook.Draft q){loading=true;try{selected=q;id.setText(q.id());name.setText(q.name());description.setText(q.description());npc.setSelectedItem(q.npc());region.setSelectedItem(q.region());race.setSelectedItem(q.race());domains();domain.setSelectedItem(q.domain());level.setValue(q.minimumLevel());unchosen.setSelected(q.unchosenDomain());reset.setSelected(q.resetContract());prerequisites.setText(String.join(",",q.prerequisites()));var d=q.definition();xp.setValue(d.xp());coins.setValue(d.coins());item.setSelectedItem(d.item());quantity.setValue(d.quantity());objectives.clear();d.objectives().forEach(objectives::addElement);}finally{loading=false;}}
    void commit(){if(selected==null)return;var d=new QuestService.Definition(Collections.list(objectives.elements()),(Integer)xp.getValue(),(Integer)coins.getValue(),(String)item.getSelectedItem(),(Integer)quantity.getValue());String required=prerequisites.getText().strip();var next=new QuestBook.Draft(id.getText().strip(),name.getText().strip(),description.getText(),(String)npc.getSelectedItem(),(String)region.getSelectedItem(),(String)race.getSelectedItem(),(Integer)level.getValue(),(String)domain.getSelectedItem(),unchosen.isSelected(),required.isEmpty()?java.util.List.of():Arrays.stream(required.split(",",-1)).map(String::strip).toList(),d,reset.isSelected());int at=quests.indexOf(selected);if(at<0)throw new IllegalStateException("Missão selecionada ausente");if(!next.equals(selected)){quests.set(at,next);dirty=true;}selected=next;}
    QuestBook book(){commit();return new QuestBook(1,quests);}
    void validateBook(){var errors=book().validate();diagnostics.setText(errors.isEmpty()?"Documento válido. Domínios e habilidades não são concedidos por configuração visual.":String.join("\n",errors));}
    void addObjective(){JComboBox<String> type=new JComboBox<>(new String[]{"kill","collect","talk","visit"}),target=new JComboBox<>();Runnable targets=()->{target.removeAllItems();String kind=switch((String)type.getSelectedItem()){case "kill"->"enemy";case "collect"->"item";case "talk"->"npc";default->"region";};RpgContent.builtin().all(kind).stream().map(RpgContent.Definition::id).sorted().forEach(target::addItem);};type.addActionListener(e->targets.run());targets.run();JSpinner count=new JSpinner(new SpinnerNumberModel(1,1,100,1));JPanel form=new JPanel(new GridLayout(0,2));form.add(new JLabel("Tipo"));form.add(type);form.add(new JLabel("Alvo"));form.add(target);form.add(new JLabel("Quantidade"));form.add(count);if(JOptionPane.showConfirmDialog(this,form,"Objetivo",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){objectives.addElement(new QuestService.Objective((String)type.getSelectedItem(),(String)target.getSelectedItem(),(Integer)count.getValue()));dirty=true;}}
    void move(int direction){int i=objectiveList.getSelectedIndex(),next=i+direction;if(i<0||next<0||next>=objectives.size())return;var value=objectives.remove(i);objectives.add(next,value);objectiveList.setSelectedIndex(next);dirty=true;}
    boolean discard(){commit();return !dirty||JOptionPane.showConfirmDialog(this,"Há alterações não salvas. Descartar?","Quest Builder",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION;}
    Path choose(boolean save){JFileChooser picker=new JFileChooser(file==null?null:file.toFile());picker.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("Missões Spirit Gate (*.sgquest)","sgquest"));if((save?picker.showSaveDialog(this):picker.showOpenDialog(this))!=JFileChooser.APPROVE_OPTION)return null;Path path=picker.getSelectedFile().toPath();return save&&!path.toString().endsWith(".sgquest")?Path.of(path+".sgquest"):path;}
    void open(){if(!discard())return;Path target=choose(false);if(target==null)return;busy=true;status.setText("Carregando missões...");new SwingWorker<QuestBook,Void>(){protected QuestBook doInBackground()throws Exception{return QuestDocuments.load(target);}protected void done(){busy=false;try{var b=get();quests.clear();quests.addAll(b.quests());show(quests.get(0));filter();file=target;dirty=false;status.setText("Missões abertas: "+target);}catch(Exception e){problem(e);}}}.execute();}
    void save(boolean export){var snapshot=book();snapshot.requireValid();Path target=export||file==null?choose(true):file;if(target==null)return;busy=true;status.setText("Validando e gravando...");new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{QuestDocuments.save(target,snapshot);return null;}protected void done(){busy=false;try{get();if(!export){file=target;dirty=false;}status.setText((export?"Exportado para sessão sintética: ":"Salvo: ")+target);}catch(Exception e){problem(e);}}}.execute();}
    void problem(Exception e){diagnostics.setText(e.getCause()==null?e.getMessage():e.getCause().getMessage());status.setText("Operação recusada; documento anterior preservado.");}
    void openBackup(){if(!discard())return;Path target=choose(false);if(target==null)return;Path backup=target.toString().endsWith(".bak")?target:Path.of(target+".bak");busy=true;status.setText("Validando backup...");new SwingWorker<QuestBook,Void>(){protected QuestBook doInBackground()throws Exception{return QuestDocuments.load(backup);}protected void done(){busy=false;try{var b=get();quests.clear();quests.addAll(b.quests());show(quests.get(0));filter();file=null;dirty=true;status.setText("Backup aberto. Salve como novo arquivo para preservar o original.");}catch(Exception e){problem(e);}}}.execute();}
}
